<script setup>
import { onMounted, ref } from "vue"; import { getAuditLogs } from "../../services/adminRepository"; const rows=ref([]),total=ref(0),page=ref(1),loading=ref(true),error=ref(""); async function load(){loading.value=true;try{const r=await getAuditLogs({page:page.value});rows.value=r.items;total.value=r.total}catch(e){error.value=e.response?.data?.detail||e.message||"加载失败"}finally{loading.value=false}} onMounted(load);
</script>
<template><main class="portal-page admin-portal page-enter"><div class="portal-heading"><div><span class="portal-kicker">安全与追踪</span><h1>操作日志</h1><p>记录管理端关键变更，不保存密码、Token 或敏感配置。</p></div><button class="secondary-button" @click="load">刷新</button></div><div v-if="loading" class="portal-loading"><i v-for="n in 4" :key="n"></i></div><div v-else-if="error" class="portal-error">{{error}}</div><section v-else class="portal-panel account-table"><div class="account-head"><span>时间</span><span>操作者</span><span>动作</span><span>对象</span><span>结果</span><span>说明</span></div><article v-for="row in rows" :key="row.id" class="account-row"><span>{{new Date(row.created_at).toLocaleString('zh-CN')}}</span><span>{{row.actor_name_snapshot}}</span><span>{{row.action}}</span><span>{{row.target_type||'—'}} {{row.target_id||''}}</span><b>{{row.result}}</b><span>{{row.description}}</span></article><div v-if="!rows.length" class="portal-empty">暂无审计记录</div></section><div class="tch-pagination"><button :disabled="page<=1" @click="page--;load()">上一页</button><span>{{page}}</span><button :disabled="page>=Math.ceil(total/20)" @click="page++;load()">下一页</button></div></main></template>
